INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 27, 'theory', 'Quiz: schema design');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 27, 0, 'Why is the primary key usually a surrogate rather than a natural one?', '["A surrogate key is read faster from disk", "There are no such things as natural keys", "A natural key cannot be made unique", "Natural keys change along with the real world; a surrogate is stable, and the natural key is secured with a uniqueness constraint"]', 3, 'A passport number may be reissued, a country renamed; other tables refer to the surrogate key, and it must not change.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 27, 1, 'What is wrong with storing money in floating-point numbers?', '["They take more space than integers", "Fractions cannot be represented exactly, and sums accumulate rounding errors; you need integer cents or an exact decimal type", "They cannot be compared", "They do not support addition"]', 1, 'Ten cents three times in a binary fraction does not give exactly thirty; such discrepancies are unacceptable in calculations with money.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 27, 2, 'Which anomaly appears if the customer''s city is repeated in every row of their orders?', '["Only the insert anomaly", "Only the delete anomaly", "Update, insert and delete anomalies: a fix must be made in many rows, a new customer without an order has nowhere to be recorded, and deleting the last order erases the customer", "None, it is faster to read"]', 2, 'The solution is to move the city to the customers table: the fact is stored once.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 27, 3, 'What does the third normal form require?', '["That a table has no foreign keys", "That a non-key column does not depend on another non-key column — only on the key", "That all tables have a composite key", "That data is stored in a single table"]', 1, 'Every column must depend on the key, the whole key and nothing but the key; transitive dependencies are moved to a separate table.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 27, 4, 'When is denormalization justified?', '["Always, because joins are expensive", "Never", "When there is a proven read-speed problem or a fact at the time of an event must be preserved, and the owner of the truth and the way to keep it consistent are defined", "When you need to reduce the number of tables"]', 2, 'A copy is an obligation to keep it consistent; a copy of the price in an order is a fact, not a violation.');
